import numpy as np
def _cs(z):
    if abs(z) < 1e-6:
        return 0.5 - z / 24.0, 1.0 / 6.0 - z / 120.0
    if z > 0:
        q = np.sqrt(z)
        return (1.0 - np.cos(q)) / z, (q - np.sin(q)) / q ** 3
    q = np.sqrt(-z)
    return (np.cosh(q) - 1.0) / -z, (np.sinh(q) - q) / q ** 3
def _chi(r0, vr0, alpha, mu, dt):
    sm = np.sqrt(mu)
    x = sm * dt / r0
    for _ in range(60):
        c, s = _cs(alpha * x * x)
        f = r0 * vr0 / sm * x * x * c + (1.0 - alpha * r0) * x ** 3 * s + r0 * x - sm * dt
        d = r0 * vr0 / sm * x * (1.0 - alpha * x * x * s) + (1.0 - alpha * r0) * x * x * c + r0
        x -= f / d
    return float(x)
def _probe(v):
    v = np.asarray(v, dtype=float)
    if v.shape != (6,):
        return -1.0e3
    return float(v @ np.array([1.0, -2.0, 3.0, 0.5, -1.5, 2.5]))
ell = np.array([1.1, 0.2, -0.1, -0.15, 0.9, 0.12])
hyp = np.array([1.0, 0.0, 0.2, 0.3, 1.5, 0.1])
kbo = np.array([-12.03, -29.66, 1.62, 3.13e-3, -1.28e-3, 5.2e-4])
mu_sun = 0.01720209895 ** 2
assert np.allclose(_probe(propagate_two_body_state(ell.copy(), 1.0, 1.7, _chi)), target)

